using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, RecordedRequest Request)> Authorize(int status, string body)
    {
        using var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);
        return (outcome, Assert.Single(provider.Requests));
    }

    [Fact]
    public async Task Sends_the_authorization_as_a_json_post_to_the_authorizations_endpoint()
    {
        var (_, request) = await Authorize(200, """{"status":"approved"}""");

        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_approved()
    {
        var (outcome, _) = await Authorize(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_declined()
    {
        var (outcome, _) = await Authorize(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_declined_whatever_the_body()
    {
        var (outcome, _) = await Authorize(402, """{"error":"insufficient_funds"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"result":"approved"}""")]
    [InlineData("""null""")]
    public async Task An_answer_that_does_not_clearly_say_approved_is_never_approved(string body)
    {
        var (outcome, _) = await Authorize(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_answer_that_is_not_json_is_an_error_not_an_approval()
    {
        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize(200, "<html>oops</html>"));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_not_as_decisions(int status)
    {
        await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(status, """{"status":"approved"}"""));
    }
}
